// Apply scripts/quiz-corrections.mjs across every refined book.
//
// The quizzes are regenerated by the refine pass, which is where the wrong answers come
// from; this runs after it, in the build chain, so a correction survives a rebuild. It
// is idempotent — a second run changes nothing — and it reports corrections whose
// question has gone rather than letting them rot as silent no-ops.
//
// Run: node scripts/fix-quiz-content.mjs
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { applyQuizCorrections, staleQuizCorrections } from "./quiz-corrections.mjs";

const APP = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const REFINED = path.join(APP, "public", "content", "refined");

if (!fs.existsSync(REFINED)) {
  console.log("fix-quiz-content: no refined content — skipping.");
  process.exit(0);
}

let applied = 0;
for (const book of fs.readdirSync(REFINED).sort()) {
  const dir = path.join(REFINED, book);
  if (!fs.statSync(dir).isDirectory()) continue;
  for (const file of fs.readdirSync(dir).filter((f) => f.endsWith(".json"))) {
    const full = path.join(dir, file);
    let mod;
    try { mod = JSON.parse(fs.readFileSync(full, "utf8")); } catch { continue; }
    let touched = false;
    for (const lesson of mod.lessons ?? []) {
      for (const fix of applyQuizCorrections(lesson, book)) {
        console.log(`fix-quiz-content: ${book}/${lesson.slug} — ${fix.match}`);
        applied++;
        touched = true;
      }
    }
    if (touched) fs.writeFileSync(full, JSON.stringify(mod, null, 2) + "\n");
  }
}

const stale = staleQuizCorrections(REFINED);
console.log(`fix-quiz-content: ${applied} correction(s) applied, ${stale.length} stale.`);
for (const s of stale) console.log(`  STALE  ${s.book}/${s.lessonSlug} — ${s.why} — « ${s.match} »`);
